func (s *ManualCommitStrategy) PostCommit(ctx context.Context) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	_, openRepoSpan := perf.Start(ctx, "open_repository_and_head")
	repo, err := OpenRepository(ctx)
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}
	defer repo.Close()

	// Get HEAD commit to check for trailer
	head, err := repo.Head()
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	// Check if commit has checkpoint trailer (ParseCheckpoint validates format)
	checkpointID, found := trailers.ParseCheckpoint(commit.Message)
	openRepoSpan.End()

	if !found {
		// No trailer — user removed it or it was never added (mid-turn commit).
		// Still update BaseCommit for active sessions so future commits can match.
		s.postCommitUpdateBaseCommitOnly(ctx, head)
		return nil
	}

	_, findSessionsSpan := perf.Start(ctx, "find_sessions_for_worktree")
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		return nil
	}

	// Find all active sessions for this worktree
	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	findSessionsSpan.RecordError(err)
	findSessionsSpan.End()

	if err != nil || len(sessions) == 0 {
		logging.Warn(logCtx, "post-commit: no active sessions despite trailer",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", checkpointID.String()),
		)
		return nil
	}

	// Build transition context
	isRebase := isGitSequenceOperation(ctx)
	transitionCtx := session.TransitionContext{
		IsRebaseInProgress: isRebase,
	}

	if isRebase {
		logging.Debug(logCtx, "post-commit: rebase/sequence in progress, skipping phase transitions",
			slog.String("strategy", "manual-commit"),
		)
	}

	// Track shadow branch names and whether they can be deleted
	shadowBranchesToDelete := make(map[string]struct{})
	// Track active sessions that were NOT condensed — their shadow branches must be preserved
	uncondensedActiveOnBranch := make(map[string]bool)

	newHead := head.Hash().String()

	// Pre-resolve HEAD tree and parent tree once for the entire PostCommit.
	// These are immutable within this hook invocation and used by multiple
	// per-session functions (filesOverlapWithContent, filesWithRemainingAgentChanges,
	// calculateSessionAttributions).
	_, resolveTreesSpan := perf.Start(ctx, "resolve_commit_trees")
	var headTree *object.Tree
	if t, err := commit.Tree(); err == nil {
		headTree = t
	}
	var parentTree *object.Tree
	if commit.NumParents() > 0 {
		if parent, err := commit.Parent(0); err == nil {
			if t, err := parent.Tree(); err == nil {
				parentTree = t
			}
		}
	}

	committedFileSet := filesChangedInCommit(ctx, worktreePath, commit, headTree, parentTree)
	resolveTreesSpan.End()

	// Compute union of all sessions' FilesTouched for cross-session attribution,
	// and count sessions whose tracked files overlap with committed files.
	allAgentFiles := make(map[string]struct{})
	sessionsWithCommittedFiles := 0
	for _, state := range sessions {
		if state.FullyCondensed && state.Phase == session.PhaseEnded {
			continue
		}
		for _, f := range state.FilesTouched {
			allAgentFiles[f] = struct{}{}
			if _, ok := committedFileSet[f]; ok {
				sessionsWithCommittedFiles++
				break // count each session at most once
			}
		}
	}

	loopCtx, processSessionsLoop := perf.StartLoop(ctx, "process_sessions")
	for _, sess := range sessions {
		if sess.FullyCondensed && sess.Phase == session.PhaseEnded {
			continue
		}
		sessionID := sess.SessionID
		iterCtx, iterSpan := processSessionsLoop.Iteration(loopCtx)
		mutErr := MutateSessionState(iterCtx, sessionID, func(state *SessionState) error {
			s.postCommitProcessSessionLocked(iterCtx, repo, state, &transitionCtx, checkpointID,
				head, commit, newHead, worktreePath, headTree, parentTree,
				committedFileSet, shadowBranchesToDelete, uncondensedActiveOnBranch, allAgentFiles,
				sessionsWithCommittedFiles)
			return nil
		})
		if mutErr != nil && !errors.Is(mutErr, ErrStateNotFound) {
			logging.Warn(logCtx, "post-commit: session mutation failed",
				slog.String("session_id", sessionID),
				slog.String("error", mutErr.Error()))
		}
		iterSpan.End()
	}
	processSessionsLoop.End()

	if err := s.updateCombinedAttributionForCheckpoint(ctx, repo, checkpointID, headTree, parentTree, worktreePath); err != nil {
		logging.Warn(logCtx, "failed to update combined checkpoint attribution",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", err.Error()))
	}

	// Clean up shadow branches — only delete when ALL sessions on the branch are non-active
	// or were condensed during this PostCommit.
	_, cleanupBranchesSpan := perf.Start(ctx, "cleanup_shadow_branches")
	for shadowBranchName := range shadowBranchesToDelete {
		if uncondensedActiveOnBranch[shadowBranchName] {
			logging.Debug(logCtx, "post-commit: preserving shadow branch (active session exists)",
				slog.String("shadow_branch", shadowBranchName),
			)
			continue
		}
		if err := deleteShadowBranch(ctx, repo, shadowBranchName); err != nil {
			logging.Warn(logCtx, "failed to clean up shadow branch",
				slog.String("shadow_branch", shadowBranchName),
				slog.String("error", err.Error()))
		} else {
			logging.Info(logCtx, "shadow branch deleted",
				slog.String("strategy", "manual-commit"),
				slog.String("shadow_branch", shadowBranchName),
			)
		}
	}
	cleanupBranchesSpan.End()

	if stale := countWarnableStaleEndedSessions(repo, sessions); stale >= staleEndedSessionWarnThreshold {
		warnStaleEndedSessions(ctx, stale)
	}

	return nil
}

// updateCombinedAttributionForCheckpoint computes holistic attribution across all sessions.
// Instead of summing per-session numbers (which inflates totals because each session
// independently counts the full commit), this diffs parent→HEAD once and classifies
// lines as agent or human based on the union of all sessions' files_touched.
func (s *ManualCommitStrategy) updateCombinedAttributionForCheckpoint(
	ctx context.Context,
	repo *git.Repository,
	checkpointID id.CheckpointID,
	headTree, parentTree *object.Tree,
	repoDir string,
) error {
	logCtx := logging.WithComponent(ctx, "attribution")
	// RefFetcher: the attribution backfill's absence probe fetches a ref that
	// exists remotely but not locally. Bounded budget + the store's failure
	// memo keep a dead network from stalling the post-commit hook.
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{
		RefFetcher:  remote.HookCheckpointRefFetcher(),
		ReadRemotes: CheckpointReadRemotes(ctx),
	})
	if err != nil {
		return fmt.Errorf("open checkpoint store: %w", err)
	}
	store := stores.Persistent

	summary, err := store.Read(ctx, checkpointID)
	if err != nil {
		return fmt.Errorf("reading checkpoint summary: %w", err)
	}
	if summary == nil || len(summary.Sessions) <= 1 {
		return nil
	}

	// Collect union of files_touched from sessions that had real checkpoints (SaveStep ran).
	// Sessions with no SaveStep steps (e.g., commit-only sessions) use a fallback that
	// includes ALL committed files, which would incorrectly classify human-created files as agent work.
	// Gate on SaveStepCount (the honest "SaveStep ran" signal), not CheckpointsCount —
	// CheckpointsCount is now a prompt count floored at 1, so it's no longer 0 for these sessions.
	// Old metadata lacks SaveStepCount → 0 → conservatively skipped, matching prior behavior.
	agentFiles := make(map[string]struct{})
	for i := range len(summary.Sessions) {
		metadata, readErr := store.ReadSessionMetadata(ctx, checkpointID, i)
		if readErr != nil || metadata == nil {
			continue
		}
		if metadata.SaveStepCount == 0 {
			continue // Skip sessions that used the filesTouched fallback
		}
		for _, f := range metadata.FilesTouched {
			agentFiles[f] = struct{}{}
		}
	}

	if len(agentFiles) == 0 {
		return nil
	}

	// Get all files changed in this commit (parent → HEAD)
	allChangedFiles, err := getAllChangedFiles(ctx, parentTree, headTree, repoDir, "", "")
	if err != nil {
		logging.Warn(logCtx, "combined attribution: failed to enumerate changed files",
			slog.String("error", err.Error()))
		return nil
	}

	// Classify each changed file as agent or human and count lines
	var agentAdded, agentRemoved, humanAdded, humanRemoved int
	for _, filePath := range allChangedFiles {
		// Skip CLI/agent config metadata — not human or agent code work
		if strings.HasPrefix(filePath, ".entire/") || strings.HasPrefix(filePath, paths.EntireMetadataDir+"/") ||
			strings.HasPrefix(filePath, ".claude/") {
			continue
		}

		parentContent := getFileContent(parentTree, filePath)
		headContent := getFileContent(headTree, filePath)
		_, added, removed := diffLines(parentContent, headContent)

		if _, isAgent := agentFiles[filePath]; isAgent {
			agentAdded += added
			agentRemoved += removed
		} else {
			humanAdded += added
			humanRemoved += removed
		}
	}

	totalLinesChanged := agentAdded + agentRemoved + humanAdded + humanRemoved
	totalCommitted := agentAdded + humanAdded

	var agentPercentage float64
	if totalLinesChanged > 0 {
		agentPercentage = float64(agentAdded+agentRemoved) / float64(totalLinesChanged) * 100
	}

	combined := &checkpoint.Attribution{
		CalculatedAt:      time.Now().UTC(),
		AgentLines:        agentAdded,
		AgentRemoved:      agentRemoved,
		HumanAdded:        humanAdded,
		HumanRemoved:      humanRemoved,
		TotalCommitted:    totalCommitted,
		TotalLinesChanged: totalLinesChanged,
		AgentPercentage:   agentPercentage,
		MetricVersion:     2,
	}

	logging.Info(logCtx, "combined attribution calculated",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Int("sessions", len(summary.Sessions)),
		slog.Int("agent_files", len(agentFiles)),
		slog.Int("agent_lines", agentAdded),
		slog.Int("human_added", humanAdded),
		slog.Float64("agent_percentage", agentPercentage),
	)

	if err := store.Write(ctx, checkpoint.CheckpointAttribution{CheckpointID: checkpointID, Attribution: combined}); err != nil {
		return fmt.Errorf("persisting combined attribution: %w", err)
	}

	return nil
}

// postCommitProcessSessionLocked handles a single session within the PostCommit loop.
// Pre-resolved git objects (headTree, parentTree) are shared across all sessions;
// per-session shadow ref/tree are resolved once here and threaded through sub-calls.
//
// MUST be called from inside MutateSessionState. Mutations to state are persisted
// by the caller's outer save — calling this function standalone silently loses
// every field change (StepCount, FilesTouched, CheckpointTranscriptStart, …).
func (s *ManualCommitStrategy) postCommitProcessSessionLocked(
	ctx context.Context,
	repo *git.Repository,
	state *SessionState,
	transitionCtx *session.TransitionContext,
	checkpointID id.CheckpointID,
	head *plumbing.Reference,
	commit *object.Commit,
	newHead string,
	repoDir string,
	headTree, parentTree *object.Tree,
	committedFileSet map[string]struct{},
	shadowBranchesToDelete map[string]struct{},
	uncondensedActiveOnBranch map[string]bool,
	allAgentFiles map[string]struct{},
	sessionsWithCommittedFiles int,
) {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	reservedCheckpointID := state.PendingCondensationID()
	if reservedCheckpointID != id.EmptyCheckpointID && reservedCheckpointID != checkpointID {
		logging.Warn(logCtx, "post-commit: preserving interrupted condensation with a different checkpoint ID",
			slog.String("session_id", state.SessionID),
			slog.String("reserved_checkpoint_id", reservedCheckpointID.String()),
			slog.String("commit_checkpoint_id", checkpointID.String()))
		uncondensedActiveOnBranch[shadowBranchName] = true
		return
	}

	// Pre-resolve shadow branch ref and tree for this session.
	// These are read 4+ times across sessionHasNewContent, filesOverlapWithContent,
	// CondenseSession, filesWithRemainingAgentChanges, and calculateSessionAttributions.
	_, resolveShadowBranchSpan := perf.Start(ctx, "resolve_shadow_branch")
	var shadowRef *plumbing.Reference
	var shadowTree *object.Tree
	if ref, refErr := repo.Reference(plumbing.NewBranchReferenceName(shadowBranchName), true); refErr == nil {

		shadowRef = ref
		if sc, scErr := repo.CommitObject(ref.Hash()); scErr == nil {
			if st, stErr := sc.Tree(); stErr == nil {
				shadowTree = st
			}
		}
	}
	resolveShadowBranchSpan.End()

	// Check for new content (needed for TransitionContext and condensation).
	// Fail-open: if content check errors, assume new content exists so we
	// don't silently skip data that should have been condensed.
	//
	// For ACTIVE sessions: the commit has a checkpoint trailer (verified above),
	// meaning PrepareCommitMsg already determined this commit is session-related.
	// The trailer is only added when either:
	//   - No TTY (agent/subagent committing) — added unconditionally
	//   - TTY (human committing) — added after content detection confirmed agent work
	// In both cases, PrepareCommitMsg already validated this commit. We trust
	// that decision here. Transcript-based re-validation is unreliable because
	// subagent transcripts may not be available yet (subagent still running).
	_, checkContentSpan := perf.Start(ctx, "check_session_content")
	var hasNew bool
	if state.Phase.IsActive() {
		hasNew = true
	} else {
		var contentErr error
		hasNew, contentErr = s.sessionHasNewContent(ctx, repo, state, contentCheckOpts{shadowTree: shadowTree})
		if contentErr != nil {
			hasNew = true
			logging.Debug(logCtx, "post-commit: error checking session content, assuming new content",
				slog.String("session_id", state.SessionID),
				slog.String("error", contentErr.Error()),
			)
		}
	}
	transitionCtx.HasFilesTouched = len(state.FilesTouched) > 0

	// Save FilesTouched BEFORE TransitionAndLog — the handler's condensation
	// clears it, but we need the original list for carry-forward computation.
	// Only fall back to transcript extraction for ACTIVE sessions — IDLE/ENDED
	// sessions have FilesTouched already populated by SaveStep/mergeFilesTouched.
	var filesTouchedBefore []string
	if state.Phase.IsActive() {
		filesTouchedBefore = s.resolveFilesTouched(ctx, state)
	} else if len(state.FilesTouched) > 0 {
		filesTouchedBefore = make([]string, len(state.FilesTouched))
		copy(filesTouchedBefore, state.FilesTouched)
	}
	checkContentSpan.End()

	logging.Debug(logCtx, "post-commit: carry-forward prep",
		slog.String("session_id", state.SessionID),
		slog.Bool("is_active", state.Phase.IsActive()),
		slog.String("transcript_path", state.TranscriptPath),
		slog.Int("files_touched_before", len(filesTouchedBefore)),
		slog.Any("files", filesTouchedBefore),
	)

	// Run the state machine transition with handler for strategy-specific actions.
	_, transitionAndCondenseSpan := perf.Start(ctx, "transition_and_condense")
	handler := &postCommitActionHandler{
		s:                          s,
		ctx:                        ctx,
		repo:                       repo,
		checkpointID:               checkpointID,
		head:                       head,
		commit:                     commit,
		newHead:                    newHead,
		repoDir:                    repoDir,
		shadowBranchName:           shadowBranchName,
		shadowBranchesToDelete:     shadowBranchesToDelete,
		committedFileSet:           committedFileSet,
		hasNew:                     hasNew,
		filesTouchedBefore:         filesTouchedBefore,
		headTree:                   headTree,
		parentTree:                 parentTree,
		shadowRef:                  shadowRef,
		shadowTree:                 shadowTree,
		allAgentFiles:              allAgentFiles,
		sessionsWithCommittedFiles: sessionsWithCommittedFiles,
	}

	if err := TransitionAndLog(ctx, state, session.EventGitCommit, *transitionCtx, handler); err != nil {
		logging.Warn(logCtx, "post-commit action handler error",
			slog.String("error", err.Error()))
	}
	transitionAndCondenseSpan.End()

	// Record checkpoint ID for ACTIVE sessions so HandleTurnEnd can finalize
	// with full transcript. IDLE/ENDED sessions already have complete transcripts.
	// NOTE: This check runs AFTER TransitionAndLog updated the phase. It relies on
	// ACTIVE + GitCommit → ACTIVE (phase stays ACTIVE). If that state machine
	// transition ever changed, this guard would silently stop recording IDs.
	if handler.condensed && state.Phase.IsActive() {
		state.TurnCheckpointIDs = append(state.TurnCheckpointIDs, checkpointID.String())
	}

	// Carry forward remaining uncommitted files so the next commit gets its
	// own checkpoint ID. This applies to ALL phases — if a user splits their
	// commit across two `git commit` invocations, each gets a 1:1 checkpoint.
	// Uses content-aware comparison: if user did `git add -p` and committed
	// partial changes, the file still has remaining agent changes to carry forward.
	_, carryForwardSpan := perf.Start(ctx, "carry_forward_files")
	if handler.condensed {
		remainingFiles := filesWithRemainingAgentChanges(ctx, repo, shadowBranchName, commit, filesTouchedBefore, committedFileSet, overlapOpts{
			headTree:   headTree,
			shadowTree: shadowTree,
		})
		state.FilesTouched = remainingFiles
		logging.Debug(logCtx, "post-commit: carry-forward decision (content-aware)",
			slog.String("session_id", state.SessionID),
			slog.Int("files_touched_before", len(filesTouchedBefore)),
			slog.Int("committed_files", len(committedFileSet)),
			slog.Int("remaining_files", len(remainingFiles)),
			slog.Any("remaining", remainingFiles),
			slog.Any("committed_files", committedFileSet),
		)
		if len(remainingFiles) > 0 {
			s.carryForwardToNewShadowBranch(ctx, repo, state, remainingFiles)
		}

		// Clear filesystem prompt.txt only when ALL files are committed.
		// If carry-forward files remain, the prompt must persist so the next
		// condensation (triggered by the next commit) can read it.
		if len(state.FilesTouched) == 0 {
			clearFilesystemPrompt(ctx, state.SessionID)
		}
	}
	carryForwardSpan.End()

	// Mark ENDED sessions as fully condensed when there's nothing left to do.
	// Either we just condensed (no carry-forward remains) or there was never any
	// new content. PostCommit will skip these on future commits; they persist only
	// for LastCheckpointID (amend trailer restoration).
	if state.Phase == session.PhaseEnded && len(state.FilesTouched) == 0 && (handler.condensed || !hasNew) {
		state.FullyCondensed = true
	}

	// Pin a review session to the single checkpoint it was just condensed into.
	// A review is a read-only one-shot: it touches no files, so it never accrues
	// shadow-branch content and the FullyCondensed branch above never fires for
	// it. Left active, it stays in this worktree's session set and gets
	// re-condensed into every subsequent commit — which is how one review ends
	// up attributed to many unrelated checkpoints (its prompt rendering once per
	// checkpoint on the session page). Once condensed, its transcript is captured
	// and it has nothing further to contribute, so mark it terminal here. Gated
	// on handler.condensed so it only fires after the review actually landed in a
	// checkpoint — a review skipped by the read-only gate is never written to a
	// checkpoint and stays eligible to attach to a later one.
	if state.Kind.IsReview() && handler.condensed {
		if state.EndedAt == nil {
			endedAt := time.Now().UTC()
			state.EndedAt = &endedAt
		}
		state.Phase = session.PhaseEnded
		state.FullyCondensed = true
	}

	// State is saved by the outer MutateSessionState in PostCommit.

	// Only preserve shadow branch for active sessions that were NOT condensed.
	// Condensed sessions already have their data on entire/checkpoints/v1.
	if state.Phase.IsActive() && !handler.condensed {
		uncondensedActiveOnBranch[shadowBranchName] = true
	}
}

// condenseAndUpdateState runs condensation for a session and updates state afterward.
// Returns true if condensation succeeded.
func (s *ManualCommitStrategy) condenseAndUpdateState(
	ctx context.Context,
	repo *git.Repository,
	checkpointID id.CheckpointID,
	state *SessionState,
	head *plumbing.Reference,
	shadowBranchName string,
	shadowBranchesToDelete map[string]struct{},
	committedFiles map[string]struct{},
	opts ...condenseOpts,
) bool {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	result, err := s.CondenseSession(ctx, repo, checkpointID, state, committedFiles, opts...)
	if err != nil {
		logging.Warn(logCtx, "condensation failed",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return false
	}

	if result.Skipped {
		logging.Debug(logCtx, "condensation skipped, session state unchanged",
			slog.String("session_id", state.SessionID),
			slog.String("checkpoint_id", checkpointID.String()),
		)
		return false
	}

	// Track this shadow branch for cleanup
	shadowBranchesToDelete[shadowBranchName] = struct{}{}

	// Update session state for the new base commit
	newHead := head.Hash().String()
	state.BaseCommit = newHead
	state.RealignAttributionBase(newHead)
	resetCheckpointWindow(state)
	state.CheckpointTranscriptStart = result.TotalTranscriptLines
	state.CheckpointTranscriptSize = result.TranscriptSizeBaseline

	// Clear attribution tracking — condensation already used these values
	state.PromptAttributions = nil
	state.PendingPromptAttribution = nil
	state.FilesTouched = nil

	// NOTE: filesystem prompt.txt is NOT cleared here. The caller (PostCommit handler)
	// decides whether to clear it based on carry-forward: if remaining files exist,
	// the prompt must persist so the next condensation can read it.

	// Save checkpoint ID so subsequent commits can reuse it (e.g., amend restores trailer).
	// LastCheckpointCommitHash records the exact commit SHA so the reconcile path can
	// distinguish a true reset (same SHA) from cherry-pick/rebase (same trailer, new SHA).
	state.LastCheckpointID = result.CheckpointID
	state.LastCheckpointCommitHash = newHead

	logging.Info(logCtx, "session condensed",
		slog.String("strategy", "manual-commit"),
		slog.String("session_id", state.SessionID),
		slog.String("checkpoint_id", result.CheckpointID.String()),
		slog.Int("checkpoints_condensed", result.CheckpointsCount),
		slog.Int("transcript_lines", result.TotalTranscriptLines),
	)

	return true
}

// updateBaseCommitIfChanged updates BaseCommit to newHead if it changed.
// Only updates ACTIVE sessions. IDLE/ENDED sessions should NOT have their
// BaseCommit updated, as this would cause them to be incorrectly associated
// with a new shadow branch and potentially condensed on future commits.
func (s *ManualCommitStrategy) updateBaseCommitIfChanged(ctx context.Context, state *SessionState, newHead string) {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	// Only update ACTIVE sessions. IDLE/ENDED sessions are kept around for
	// LastCheckpointID reuse and should not be advanced to HEAD.
	if !state.Phase.IsActive() {
		logging.Debug(logCtx, "post-commit: updateBaseCommitIfChanged skipped non-active session",
			slog.String("session_id", state.SessionID),
			slog.String("phase", string(state.Phase)),
		)
		return
	}
	if state.BaseCommit != newHead {
		state.BaseCommit = newHead
		// Keep AttributionBaseCommit in sync to prevent stale base drift.
		// Without this, a subsequent condensation would diff from the old base,
		// inflating human_added with lines from unrelated prior commits.
		state.RealignAttributionBase(newHead)
		logging.Debug(logCtx, "post-commit: updated BaseCommit and AttributionBaseCommit",
			slog.String("session_id", state.SessionID),
			slog.String("new_head", truncateHash(newHead)),

func (s *ManualCommitStrategy) CondenseSession(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, state *SessionState, committedFiles map[string]struct{}, opts ...condenseOpts) (*CondenseResult, error) {
	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
	var o condenseOpts
	if len(opts) > 0 {
		o = opts[0]
	}
	logCtx := logging.WithComponent(ctx, "checkpoint")
	condenseStart := time.Now()
	policy, err := readLocalCheckpointPolicy(logCtx, repo)
	if err != nil {
		return nil, fmt.Errorf("checkpoint policy could not be read: %w", err)
	}
	if !checkpointpolicy.CanSatisfyPolicy(policy) {
		warnIfCheckpointPolicyNeedsUpgrade(logCtx, policy)
		return nil, errors.New("checkpoint policy cannot be satisfied by this Entire CLI")
	}

	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	ref, hasShadowBranch := resolveShadowRef(repo, shadowBranchName, o.shadowRef)

	// Re-resolve transcript path before any reads — handles agents that relocate
	// transcripts mid-session (e.g., Cursor CLI flat → nested layout change).
	// Errors are ignored; downstream readers handle missing transcripts gracefully.
	resolveTranscriptPath(state) //nolint:errcheck,gosec // best-effort; downstream readers handle missing files

	extractStart := time.Now()
	_, extractSessionDataSpan := perf.Start(ctx, "extract_session_data")
	var shadowHash plumbing.Hash
	if hasShadowBranch {
		shadowHash = ref.Hash()
	}
	sessionData, extractErr := s.extractOrCreateSessionData(ctx, repo, ag, shadowHash, hasShadowBranch, state)
	if extractErr != nil {
		extractSessionDataSpan.RecordError(extractErr)
		extractSessionDataSpan.End()
		return nil, extractErr
	}
	extractSessionDataSpan.End()
	extractDuration := time.Since(extractStart)

	// Backfill session state token usage from the freshly-extracted transcript.
	// Copilot CLI writes session.shutdown after the hooks return, so by condensation
	// time we can recover the authoritative full-session total from the transcript
	// while keeping checkpoint metadata scoped to CheckpointTranscriptStart. The
	// recompute drops SubagentTokens (subagentsDir=""); the helper preserves the
	// cumulative subagent total across the backfill so resetCheckpointWindow's
	// baseline does not regress to nil (finding 019f5ebf-a57e).
	applyBackfilledSessionTokenUsage(ctx, ag, state, sessionData.Transcript, sessionData.TokenUsage)

	if !hasTokenUsageData(sessionData.TokenUsage) && hasTokenUsageData(state.CheckpointTokenUsage) {
		// Whole-value fallback: accumulateTokenUsage already carries SubagentTokens.
		sessionData.TokenUsage = accumulateTokenUsage(nil, state.CheckpointTokenUsage)
	} else {
		// Refill only the subagent total the recompute dropped. Runs after
		// applyBackfilledSessionTokenUsage, which needs the usage without it.
		sessionData.TokenUsage = withSubagentTokensFrom(sessionData.TokenUsage, state.CheckpointTokenUsage)
	}

	// Backfill the model from the transcript for agents that don't report it via
	// hooks (e.g., Pi records message.model but its hook events carry no model
	// field). Only fills when the model is otherwise unknown — hook-reported
	// models take precedence.
	if state.ModelName == "" {
		if model := sessionStateBackfillModel(ctx, ag, sessionData.Transcript); model != "" {
			state.ModelName = model
		}
	}

	if skipped := skipIfNothingToCondense(logCtx, sessionData, state, checkpointID, hasShadowBranch); skipped != nil {
		return skipped, nil
	}

	filterFilesTouched(sessionData, committedFiles, state)

	// sessionData.Transcript is left as the raw transcript; only the sanitized,
	// externalized, redacted copy is stored.
	externalizedTranscript, extractedAssets, transcriptSizeBaseline := prepareTranscriptForStorage(ctx, logCtx, ag, state, sessionData.Transcript)

	redactedTranscript, redactDuration := redactOrDrop(logCtx, externalizedTranscript, state.SessionID, checkpointID)
	if skipped := skipIfPostRedactionEmpty(logCtx, redactedTranscript, sessionData, state, checkpointID); skipped != nil {
		return skipped, nil
	}

	// Capture agent sidecar images (e.g. Cursor's SQLite store) after the skip
	// check, so the sqlite3 shell-out is avoided when the checkpoint is discarded.
	extractedAssets = append(extractedAssets, sidecarSessionImages(ctx, logCtx, ag, state)...)

	// Materialize this session's subagent task records (#2058): every
	// completed-or-in-flight record's transcript is resolved, redacted, and
	// stored under this checkpoint's tasks/<tool-use-id>/ subtree.
	taskPayloads, extractedAssets := s.materializeTaskRecords(ctx, logCtx, ag, state, extractedAssets)

	store, err := s.getPersistentStore(ctx, repo)
	if err != nil {
		return nil, err
	}
	recovery := recoverInterruptedCondensation(
		ctx, logCtx,
		o.reconcileInterrupted && state.NeedsCondensationRecovery(),
		store, state, redactedTranscript, extractedAssets, sessionData, transcriptSizeBaseline,
	)
	if recovery.done {
		return recovery.result, recovery.err
	}

	writeOpts, attributionDuration := buildCondensationWriteOptions(
		ctx, repo, ref, state, sessionData, redactedTranscript, extractedAssets,
		taskPayloads, checkpointID, shadowBranchName, o,
	)

	writeV1Start := time.Now()
	writeCtx, writeCommittedSpan := perf.Start(ctx, "write_committed_v1")
	writeRequest := condensationSessionWriteRequest(writeOpts)
	if err := store.Write(writeCtx, writeRequest); err != nil {
		writeCommittedSpan.RecordError(err)
		writeCommittedSpan.End()
		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
	}
	writeCommittedSpan.End()
	writeV1Duration := time.Since(writeV1Start)

	// Deferred prompt-window reset: a checkpoint was written, so the window base
	// must be re-anchored — but not now. We defer until the next counted turn (in
	// persistEventMetadataToState) so two checkpoints with no prompt between them
	// report the same count instead of the second showing 0.
	state.PromptWindowResetPending = true

	logging.Debug(logCtx, "condense timings",
		slog.String("session_id", state.SessionID),
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Int64("extract_session_data_ms", extractDuration.Milliseconds()),
		slog.Int64("calculate_session_attribution_ms", attributionDuration.Milliseconds()),
		slog.Int64("redact_transcript_ms", redactDuration.Milliseconds()),
		slog.Int64("write_committed_v1_ms", writeV1Duration.Milliseconds()),
		slog.Int64("total_ms", time.Since(condenseStart).Milliseconds()),
		slog.Int("transcript_bytes", len(sessionData.Transcript)),
		slog.Int("transcript_lines", sessionData.FullTranscriptLines),
	)

	return &CondenseResult{
		CheckpointID:           checkpointID,
		SessionID:              state.SessionID,
		CheckpointsCount:       checkpointStepCount(state),
		FilesTouched:           sessionData.FilesTouched,
		Prompts:                sessionData.Prompts,
		TotalTranscriptLines:   sessionData.FullTranscriptLines,
		TranscriptSizeBaseline: transcriptSizeBaseline,
	}, nil
}

// condensationSessionWriteRequest returns the write request for one
// condensation. Every condensation write is ReservedSession, unconditionally.
//
// The tempting refinement — send ReservedSession only when this session's own
// pending attempt matches the checkpoint ID, and plain Session otherwise —
// is wrong, and wrong in a worse direction than the problem it solves. A
// checkpoint can hold several sessions, and only the one that reserved the ID
// carries the reservation in its state. Routing per session would send the
// reserving session's write to the backend the ID belongs to and every sibling's
// write to the configured primary, splitting one checkpoint across both
// backends. Reads are not symmetrical about that: a ULID resolves from git-refs
// only, so the siblings written to the branch would simply be invisible. See
// TestCondensationSessionWrites_KeepSharedReservedCheckpointInOneBackend.
//
// The cost of routing everything by ID format is narrow. It only diverges from
// the configured primary when the ID's format disagrees with the primary, and
// the two fail-soft defaults agree: GenerateCheckpointID mints hex when the
// checkpoints config cannot be read, and resolvePrimaryType defaults to
// git-branch on the same unreadable config. Reaching a mismatch on a *fresh* ID
// therefore takes a config read that succeeds for one call and fails for the
// other — and even then the checkpoint stays readable, because a hex ID under a
// git-refs primary falls through to the branch on read.
//
// If the per-checkpoint routing decision ever does need to be conditional, it
// has to be made once for the whole checkpoint (from the commit trailer or a
// checkpoint-level flag), never per session.
func condensationSessionWriteRequest(opts cpkg.WriteOptions) cpkg.WriteRequest {
	return cpkg.ReservedSession(opts)
}

func buildCondensationWriteOptions(
	ctx context.Context,
	repo *git.Repository,
	shadowRef *plumbing.Reference,
	state *SessionState,
	sessionData *ExtractedSessionData,
	transcript redact.RedactedBytes,
	assets []cpkg.TranscriptAsset,
	tasks []cpkg.TaskPayload,
	checkpointID id.CheckpointID,
	shadowBranchName string,
	o condenseOpts,
) (cpkg.WriteOptions, time.Duration) {
	authorName, authorEmail := GetGitAuthorFromRepo(repo)
	attrBase := state.AttributionBaseCommit
	if attrBase == "" {
		attrBase = state.BaseCommit
	}

	attributionStart := time.Now()
	attrCtx, attributionSpan := perf.Start(ctx, "calculate_session_attribution")
	attribution := calculateSessionAttributions(attrCtx, repo, shadowRef, sessionData, state, attributionOpts{
		headTree:              o.headTree,
		parentTree:            o.parentTree,
		repoDir:               o.repoDir,
		attributionBaseCommit: attrBase,
		parentCommitHash:      o.parentCommitHash,
		headCommitHash:        o.headCommitHash,
		allAgentFiles:         o.allAgentFiles,
	})
	attributionSpan.End()
	attributionDuration := time.Since(attributionStart)

	var summary *cpkg.Summary
	if settings.IsSummarizeEnabled(ctx) && transcript.Len() > 0 {
		summary = generateSummary(ctx, transcript, sessionData.FilesTouched, state)
	}

	// Post-commit emits regex-only blobs. OPF runs later in the
	// pre-push rewrite path, never here.
	skillEvents := mergeSkillEvents(state.SkillEvents, withSkillEventTurnID(sessionData.SkillEvents, state.TurnID))
	return cpkg.WriteOptions{
		CheckpointID:                checkpointID,
		SessionID:                   state.SessionID,
		Strategy:                    StrategyNameManualCommit,
		Branch:                      GetCurrentBranchName(repo),
		Transcript:                  transcript,
		Assets:                      assets,
		Tasks:                       tasks,
		Prompts:                     sessionData.Prompts,
		FilesTouched:                sessionData.FilesTouched,
		CheckpointsCount:            checkpointStepCount(state),
		SaveStepCount:               state.StepCount,
		EphemeralBranch:             shadowBranchName,
		AuthorName:                  authorName,
		AuthorEmail:                 authorEmail,
		Agent:                       state.AgentType,
		Model:                       state.ModelName,
		TurnID:                      state.TurnID,
		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   state.CheckpointTranscriptStart,
		TokenUsage:                  sessionData.TokenUsage,
		SkillEvents:                 skillEvents,
		SessionMetrics:              buildSessionMetrics(state),
		Attribution:                 attribution,
		PromptAttributionsJSON:      marshalPromptAttributionsIncludingPending(state),
		Summary:                     summary,
		Kind:                        string(state.Kind),
		ReviewSkills:                state.ReviewSkills,
		ReviewPrompt:                state.ReviewPrompt,
		HasReview:                   state.Kind.IsReview(),
		HasInvestigation:            state.Kind.IsInvestigate(),
		InvestigateRunID:            state.InvestigateRunID,
		InvestigateTopic:            state.InvestigateTopic,
	}, attributionDuration
}

// redactOrDrop runs redactSessionTranscript and, on failure, logs a warning
// and returns empty bytes. Drop-on-failure is the long-standing contract here:
// hooks have no retry path, and a failed redaction must not block the commit.
func redactOrDrop(logCtx context.Context, transcript []byte, sessionID string, checkpointID id.CheckpointID) (redact.RedactedBytes, time.Duration) {
	redactedTranscript, redactDuration, err := redactSessionTranscript(logCtx, transcript)
	if err != nil {
		logging.Warn(logCtx, "failed to redact transcript secrets, dropping transcript for checkpoint",
			slog.String("session_id", sessionID),
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", err.Error()),
		)
		return redact.RedactedBytes{}, redactDuration
	}
	return redactedTranscript, redactDuration
}

// skipIfNothingToCondense returns a Skipped result when there is no
// transcript, no files touched, AND no task records — nothing meaningful to
// condense, so return early instead of writing a metadata-only stub. A
// records-only session (read-only background subagent, empty parent
// transcript) must still write: its task payloads are the checkpoint's content.
//
// This check MUST run before filterFilesTouched. That function's fallback
// assigns all committed files to sessions with empty FilesTouched (designed
// for mid-turn commits where SaveStep hasn't run yet). Without this ordering,
// genuinely empty sessions (no transcript, no shadow branch, no tracked files)
// would acquire committed files from the fallback and bypass this gate.
func skipIfNothingToCondense(logCtx context.Context, sessionData *ExtractedSessionData, state *SessionState, checkpointID id.CheckpointID, hasShadowBranch bool) *CondenseResult {
	if len(sessionData.Transcript) > 0 || len(sessionData.FilesTouched) > 0 || state.HasTaskContent() {
		return nil
	}
	logging.Info(logCtx, "session skipped: no transcript or files to condense",
		slog.String("session_id", state.SessionID),
		slog.String("agent_type", string(state.AgentType)),
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Bool("has_shadow_branch", hasShadowBranch),
		slog.String("transcript_path", state.TranscriptPath),
	)
	return newSkippedResult(checkpointID, state.SessionID)
}

// skipIfPostRedactionEmpty returns a Skipped result when redaction emptied the
// transcript AND the filtered FilesTouched is also empty. Without this, a
// session that passed the pre-redaction gate but got its transcript dropped by
// a malformed-JSONL redaction error would write a metadata-only stub. A
// session with task payloads to materialize must still write even when its
// parent transcript redacts to empty.
func skipIfPostRedactionEmpty(logCtx context.Context, redactedTranscript redact.RedactedBytes, sessionData *ExtractedSessionData, state *SessionState, checkpointID id.CheckpointID) *CondenseResult {
	if redactedTranscript.Len() > 0 || len(sessionData.FilesTouched) > 0 || state.HasTaskContent() {
		return nil
	}
	logging.Info(logCtx, "session skipped: nothing to persist after redaction",
		slog.String("session_id", state.SessionID),
		slog.String("agent_type", string(state.AgentType)),
		slog.String("checkpoint_id", checkpointID.String()),
	)
	return newSkippedResult(checkpointID, state.SessionID)
}

func newSkippedResult(checkpointID id.CheckpointID, sessionID string) *CondenseResult {
	return &CondenseResult{
		CheckpointID: checkpointID,
		SessionID:    sessionID,
		Skipped:      true,
	}
}

// redactSessionTranscript redacts the transcript once for use by both the compact
// package and the checkpoint stores. Returns the redacted bytes and the duration
// of the redaction operation for perf logging. Also the redaction step
// prepareTaskTranscriptForStorage reuses for a subagent's own transcript.
func redactSessionTranscript(ctx context.Context, transcript []byte) (redact.RedactedBytes, time.Duration, error) {
	start := time.Now()
	_, span := perf.Start(ctx, "redact_transcript")
	defer span.End()

	if len(transcript) == 0 {
		return redact.RedactedBytes{}, time.Since(start), nil
	}

	redacted, err := redactSessionJSONLBytes(ctx, transcript)
