12	)
13	
14	// kindRoutingStore resolves id-keyed reads across the two git backends so a repo
15	// running git-refs and git-branch side by side (or mid-migration between them)
16	// can read checkpoints of BOTH formats without reconfiguring:
17	//
18	//   - A ULID checkpoint only ever lives in the git-refs store, so a ULID ID is
19	//     read from refs and NEVER from the branch (regardless of the active backend).
20	//   - A legacy-hex ID is read from the active (configured) primary first. When the
21	//     active primary is git-refs, it also falls back to the git-branch store,
22	//     because a hex checkpoint may still sit on the pre-migration v1 branch. Under
23	//     a git-branch primary the branch is authoritative for hex, so refs is not
24	//     consulted.
25	//
26	// List unions both backends (disjoint ID spaces). Fresh creates (Session) are NOT
27	// kind-routed: they go to the configured primary (+ mirrors) via writer, since
28	// a new checkpoint's ID is already minted to match the primary's format (see
29	// checkpoint.GenerateCheckpointID). ReservedSession writes preserve the backend
30	// chosen before an interrupted write; when a migrated copy already exists in the
31	// read-preferred backend, they update that copy too. Backfills update an existing
32	// checkpoint, so they follow the same store order as reads, though only
33	// ErrCheckpointNotFound falls through (stricter than reads) — see Write.
34	type kindRoutingStore struct {
35		writer      PersistentStore // configured primary + mirrors (fanout); handles Write
36		branch      PersistentStore // git-branch store; serves hex reads
37		refs        PersistentStore // git-refs store; serves ULID reads (+ hex under refs primary)
38		primaryType string
39	}
40	
41	// newKindRoutingStore wraps the write fanout plus the two git read stores. It
42	// preserves the optional AuthorReader capability (explain relies on it) when both
43	// read stores provide it — the built-in git backends always do.
44	func newKindRoutingStore(writer, branch, refs PersistentStore, primaryType string) PersistentStore {
45		s := &kindRoutingStore{writer: writer, branch: branch, refs: refs, primaryType: primaryType}
46		if _, ok := branch.(AuthorReader); ok {
47			if _, ok := refs.(AuthorReader); ok {
48				return &kindRoutingStoreWithAuthor{kindRoutingStore: s}
49			}
50		}
51		return s
52	}
53	
54	// readOrder returns the stores to consult for checkpointID, in priority order,
55	// per the routing rules above.
56	func (s *kindRoutingStore) readOrder(checkpointID id.CheckpointID) []PersistentStore {
57		if checkpointID.Kind() == id.KindULID {
58			return []PersistentStore{s.refs} // ULIDs only ever live in refs
59		}
60		switch s.primaryType {
61		case BackendTypeGitBranch:
62			return []PersistentStore{s.branch} // branch is authoritative for hex
63		case BackendTypeGitRefs:
64			return []PersistentStore{s.refs, s.branch} // active refs, then pre-migration branch
65		default:
66			// A non-branch/refs git-backed primary is not a real configuration today;
67			// try both git stores so a hex ID still resolves wherever it landed.
68			return []PersistentStore{s.branch, s.refs}
69		}
70	}
71	
72	// firstResolved calls read on each store in order and returns the first genuine
73	// hit (a non-absent result with no error). A non-final store that reports absent
74	// OR errors falls through to the next store, so a transient failure in one
75	// backend (e.g. a git-refs on-demand fetch error) does not hide a checkpoint that
76	// resolves in the fallback backend. The final store's result is returned as-is
77	// (hit, absent, or error), so callers still see the backend's own not-found /
78	// error signal when nothing resolved.
79	func firstResolved[T any](stores []PersistentStore, read func(PersistentStore) (T, error), absent func(T, error) bool) (T, error) {
80		var v T
81		var err error
82		for i, st := range stores {
83			v, err = read(st)
84			if i == len(stores)-1 || (err == nil && !absent(v, err)) {
85				return v, err
86			}
87		}
88		return v, err
89	}
90	
91	// checkpointNotFound reports the checkpoint-level "absent" signal: Read returns
92	// (nil, nil) — not an error — when a checkpoint does not exist.
93	func checkpointNotFound(v *CheckpointSummary, err error) bool {
94		return err == nil && v == nil
95	}
96	
97	// sessionNotFound reports the session-level "absent" signal: the session readers
98	// return ErrCheckpointNotFound when the checkpoint (or session) is missing.
99	func sessionNotFound[T any](_ T, err error) bool {
100		return errors.Is(err, ErrCheckpointNotFound)
101	}
102	
103	func (s *kindRoutingStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
104		return firstResolved(s.readOrder(checkpointID),
105			func(st PersistentStore) (*CheckpointSummary, error) { return st.Read(ctx, checkpointID) },
106			checkpointNotFound,
107		)
108	}
109	
110	func (s *kindRoutingStore) List(ctx context.Context) ([]CheckpointInfo, error) {
111		branchList, err := s.branch.List(ctx)
112		if err != nil {
113			return nil, err //nolint:wrapcheck // in-package store error surfaced verbatim
114		}
115		refsList, err := s.refs.List(ctx)
116		if err != nil {
117			return nil, err //nolint:wrapcheck // in-package store error surfaced verbatim
118		}
119		merged := make([]CheckpointInfo, 0, len(branchList)+len(refsList))
120		merged = append(merged, branchList...)
121		merged = append(merged, refsList...)
122		sortCheckpointInfosByRecency(merged)
123		// Dedup by ID: during coexistence/migration the same checkpoint can appear in
124		// both backends (a ULID mirrored to the branch, or a hex still on the branch
125		// and also migrated into refs). Keep the first occurrence — i.e. the most
126		// recent after the sort.
127		deduped := merged[:0]
128		seen := make(map[id.CheckpointID]struct{}, len(merged))
129		for _, info := range merged {
130			if _, dup := seen[info.CheckpointID]; dup {
131				continue
132			}
133			seen[info.CheckpointID] = struct{}{}
134			deduped = append(deduped, info)
135		}
136		return deduped, nil
137	}
138	
139	// sortCheckpointInfosByRecency orders checkpoints most-recent-first by CreatedAt.
140	// Shared by the git-branch, git-refs, and routing List implementations so they
141	// present a consistent order.
142	func sortCheckpointInfosByRecency(checkpoints []CheckpointInfo) {
143		sort.Slice(checkpoints, func(i, j int) bool {
144			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
145		})
146	}
147	
148	func (s *kindRoutingStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
149		return firstResolved(s.readOrder(checkpointID),
150			func(st PersistentStore) (*SessionContent, error) {
151				return st.ReadSessionContent(ctx, checkpointID, sessionIndex)
152			},
153			sessionNotFound[*SessionContent],
154		)
155	}
156	
157	func (s *kindRoutingStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error) {
158		return firstResolved(s.readOrder(checkpointID),
159			func(st PersistentStore) (*Metadata, error) {
160				return st.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
161			},
162			sessionNotFound[*Metadata],
163		)
164	}
165	
166	func (s *kindRoutingStore) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
167		return firstResolved(s.readOrder(checkpointID),
168			func(st PersistentStore) (string, error) {
169				return st.ReadSessionPrompts(ctx, checkpointID, sessionIndex)
170			},
171			sessionNotFound[string],
172		)
173	}
174	
175	// metaAndPrompts bundles the two non-error returns of ReadSessionMetadataAndPrompts
176	// so it can flow through the single-value firstResolved helper.
177	type metaAndPrompts struct {
178		meta    *Metadata
179		prompts string
180	}
181	
182	func (s *kindRoutingStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error) {
183		mp, err := firstResolved(s.readOrder(checkpointID),
184			func(st PersistentStore) (metaAndPrompts, error) {
185				m, p, e := st.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
186				return metaAndPrompts{meta: m, prompts: p}, e //nolint:wrapcheck // in-package store error surfaced verbatim
187			},
188			sessionNotFound[metaAndPrompts],
189		)
190		return mp.meta, mp.prompts, err
191	}
192	
193	// Write routes a create (Session) to the configured primary (+ mirrors): a new
194	// checkpoint's ID is already minted to match the primary's format (see
195	// checkpoint.GenerateCheckpointID). Backfills target an EXISTING checkpoint,
196	// which — like reads — may live in either git backend (e.g. a pre-migration hex
197	// checkpoint still on the v1 branch under a git-refs primary), so they follow
198	// the read order, falling through to the next store on ErrCheckpointNotFound.
199	//
200	// The fallthrough is deliberately stricter than read routing's firstResolved
201	// (which falls through on absent OR any error): only the not-found sentinel
202	// falls through here. Redirecting a write to another backend after a transient
203	// primary failure could fork the data, so a hard error aborts and surfaces.
204	// Note the refs store's backfill absence probe fetches a locally-missing ref
205	// on demand when a fetcher is wired (refBaseForBackfill), so a checkpoint
206	// whose ref exists only remotely is fetched and backfilled in place rather
207	// than falling through to the fallback store.
208	func (s *kindRoutingStore) Write(ctx context.Context, req WriteRequest) error {
209		if reserved, ok := req.(ReservedSession); ok {
210			return s.writeReservedSession(ctx, reserved)
211		}
212		checkpointID, isBackfill := backfillTarget(req)
213		if !isBackfill {
214			return s.writer.Write(ctx, req) //nolint:wrapcheck // primary error is the operation's error, surfaced verbatim
215		}
216		stores := s.backfillOrder(checkpointID)
217		var err error
218		for i, st := range stores {
219			err = st.Write(ctx, req)
220			if !errors.Is(err, ErrCheckpointNotFound) {
221				if err == nil && i > 0 {
222					// The most consequential routing decision here: the data landed
223					// somewhere other than the configured primary, and mirrors
224					// (which follow the primary) were skipped. Record it so "why is
225					// this backfill on the v1 branch and not in refs / the mirror"
226					// stays diagnosable.
227					logging.Info(ctx, "checkpoint: backfill served by fallback store; absent from primary, mirrors skipped",
228						slog.String("checkpoint_id", checkpointID.String()),
229						slog.String("request_type", fmt.Sprintf("%T", req)))
230				}
231				return err //nolint:wrapcheck // in-package store error surfaced verbatim
232			}
233			if i < len(stores)-1 {
234				logging.Debug(ctx, "checkpoint: backfill target absent in store, trying next",
235					slog.String("checkpoint_id", checkpointID.String()),
236					slog.String("request_type", fmt.Sprintf("%T", req)),
237					slog.Int("store_index", i))
238			}
239		}
240		return err //nolint:wrapcheck // ErrCheckpointNotFound from the final store, surfaced verbatim
241	}
242	
243	func (s *kindRoutingStore) writeReservedSession(ctx context.Context, req ReservedSession) error {
244		checkpointID := WriteOptions(req).CheckpointID
245		if s.primaryType != BackendTypeGitBranch && s.primaryType != BackendTypeGitRefs {
246			// An unrecognised primary tells us nothing about which backend minted the
247			// ID, and picking one anyway would bypass the configured primary and all of
248			// its mirrors. readOrder's default arm makes the same call for reads.
249			return s.writer.Write(ctx, req) //nolint:wrapcheck // primary error is the operation's error, surfaced verbatim
250		}
251		target := s.branch
252		targetType := BackendTypeGitBranch
253		if checkpointID.Kind() == id.KindULID {
254			target = s.refs
255			targetType = BackendTypeGitRefs
256		}
257		if targetType == s.primaryType {
258			return s.writer.Write(ctx, req) //nolint:wrapcheck // primary error is the operation's error, surfaced verbatim
259		}
260	
261		readTarget := s.readOrder(checkpointID)[0]
262		updateReadTarget := false
263		if readTarget != target {
264			existing, err := readTarget.Read(ctx, checkpointID)
265			switch {
266			case err != nil:
267				// Not fatal. readOrder puts this store ahead of target for this ID, and
268				// firstResolved falls through a non-final store that errors, so the
269				// target write below still resolves through normal reads. The cost of
270				// skipping the update is a migrated copy left stale — the same lag the
271				// mirror fan-out contract already permits — whereas failing here would
272				// abandon a condensation over a transient fetch error in the backend the
273				// checkpoint is not even stored in.
274				logging.Warn(ctx, "checkpoint: reserved session could not check the read-preferred backend; writing the ID's backend only",
275					slog.String("checkpoint_id", checkpointID.String()),
276					slog.String("primary_backend", s.primaryType),
277					slog.String("error", err.Error()))
278			default:
279				updateReadTarget = existing != nil
280			}
281		}
282		if err := target.Write(ctx, req); err != nil {
283			return err //nolint:wrapcheck // target error is the operation's error, surfaced verbatim
284		}
285		if updateReadTarget {
286			// Update the readable copy directly. The original target may itself be a
287			// configured mirror, so re-entering writer fan-out would write it twice;
288			// other best-effort mirrors are allowed to lag by the fan-out contract.
289			if err := readTarget.Write(ctx, req); err != nil {
290				return err //nolint:wrapcheck // read-preferred copy must not remain stale after a successful retry
291			}
292		}
293		logging.Info(ctx, "checkpoint: reserved session written to original backend after primary changed",
294			slog.String("checkpoint_id", checkpointID.String()),
295			slog.String("target_backend", targetType),
296			slog.String("primary_backend", s.primaryType),
297			slog.Bool("updated_existing_read_target", updateReadTarget))
298		return nil
299	}
300	
301	// backfillTarget returns the checkpoint ID a backfill request updates.
302	// ok is false for Session and ReservedSession (creates) and unknown request
303	// types, which are not routed by backfillOrder.
304	//
305	// WriteRequest is a closed union: any new backfill-shaped request type MUST be
306	// added to this switch, or it silently gets create routing — primary-only, no
307	// fallback — which for a pre-migration checkpoint reintroduces the discarded-
308	// write bug this routing exists to prevent.
309	func backfillTarget(req WriteRequest) (id.CheckpointID, bool) {
310		switch r := req.(type) {
311		case SessionTranscript:
312			return r.CheckpointID, true
313		case SessionSummary:
314			return r.CheckpointID, true
315		case CheckpointAttribution:
316			return r.CheckpointID, true
317		default:
318			return id.EmptyCheckpointID, false
319		}
320	}
321	
322	// backfillOrder returns the write targets for a backfill of checkpointID, in
323	// the same priority order reads use. The store that is the configured primary
324	// is replaced by writer, so a backfill landing on the primary still fans out to
325	// mirrors; a backfill landing on a fallback store deliberately skips mirrors
326	// (mirrors follow the primary).
327	func (s *kindRoutingStore) backfillOrder(checkpointID id.CheckpointID) []PersistentStore {
328		order := s.readOrder(checkpointID)
329		targets := make([]PersistentStore, len(order))
330		for i, st := range order {
331			if s.isPrimary(st) {
332				targets[i] = s.writer
333			} else {
334				targets[i] = st
335			}
336		}
337		return targets
338	}
339	
340	// isPrimary reports whether st is the configured primary's read store.
341	func (s *kindRoutingStore) isPrimary(st PersistentStore) bool {
342		switch s.primaryType {
343		case BackendTypeGitBranch:
344			return st == s.branch
345		case BackendTypeGitRefs:
346			return st == s.refs
347		default:
348			// Not a real configuration today (buildPrimary only accepts the git
349			// backends); backfills would bypass writer and therefore mirrors.
350			return false
351		}
352	}
353	
354	// kindRoutingStoreWithAuthor adds the optional AuthorReader capability, routing
355	// GetCheckpointAuthor by the same rules as the reads.
356	type kindRoutingStoreWithAuthor struct {
357		*kindRoutingStore
358	}
359	
360	func (s *kindRoutingStoreWithAuthor) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
361		return firstResolved(s.readOrder(checkpointID),
362			func(st PersistentStore) (Author, error) {
363				ar, ok := st.(AuthorReader)
364				if !ok {
365					return Author{}, nil
366				}
367				return ar.GetCheckpointAuthor(ctx, checkpointID)
368			},
369			func(a Author, err error) bool { return err == nil && a == Author{} },
370		)
371	}
