package strategy

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"slices"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	cpkg "github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/transcript/imageextract"
	"github.com/entireio/cli/redact"
)

func transcriptForRecoveryComparison(agentType types.AgentType, transcript redact.RedactedBytes, assets []cpkg.TranscriptAsset) ([]byte, error) {
	codec := imageextract.CodecFor(agentType)
	if codec == nil || len(assets) == 0 {
		return transcript.Bytes(), nil
	}

	byName := make(map[string]agent.CompactedTranscriptAsset, len(assets))
	for _, asset := range assets {
		byName[asset.Name] = agent.CompactedTranscriptAsset{
			Name:      asset.Name,
			MediaType: asset.MediaType,
			Data:      asset.Data,
		}
	}
	reinjected, err := codec.ReinjectImages(transcript.Bytes(), func(name string) (agent.CompactedTranscriptAsset, bool) {
		asset, ok := byName[name]
		return asset, ok
	})
	if err != nil {
		return nil, fmt.Errorf("reinject transcript images: %w", err)
	}
	return reinjected, nil
}

func findInterruptedCondensation(
	ctx context.Context,
	store cpkg.PersistentStore,
	state *SessionState,
	transcript redact.RedactedBytes,
	assets []cpkg.TranscriptAsset,
) (id.CheckpointID, bool, error) {
	expectedTranscript, err := transcriptForRecoveryComparison(state.AgentType, transcript, assets)
	if err != nil {
		return id.EmptyCheckpointID, false, err
	}

	checkpoints, err := store.List(ctx)
	if err != nil {
		return id.EmptyCheckpointID, false, fmt.Errorf("list checkpoints: %w", err)
	}
	var candidateErrors []error
	for _, info := range checkpoints {
		if info.ListedStub || (info.SessionID != state.SessionID && !slices.Contains(info.SessionIDs, state.SessionID)) {
			continue
		}
		summary, readErr := store.Read(ctx, info.CheckpointID)
		if readErr != nil {
			candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s: %w", info.CheckpointID, readErr))
			continue
		}
		if summary == nil {
			candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s: %w", info.CheckpointID, cpkg.ErrCheckpointNotFound))
			continue
		}
		for sessionIndex := range len(summary.Sessions) {
			metadata, metadataErr := store.ReadSessionMetadata(ctx, info.CheckpointID, sessionIndex)
			if metadataErr != nil {
				candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d metadata: %w", info.CheckpointID, sessionIndex, metadataErr))
				continue
			}
			if metadata == nil {
				candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d metadata: %w", info.CheckpointID, sessionIndex, cpkg.ErrCheckpointNotFound))
				continue
			}
			if metadata.SessionID != state.SessionID ||
				metadata.Strategy != StrategyNameManualCommit ||
				metadata.CheckpointTranscriptStart != state.CheckpointTranscriptStart ||
				metadata.TranscriptIdentifierAtStart != state.TranscriptIdentifierAtStart ||
				metadata.CheckpointsCount != checkpointStepCount(state) ||
				metadata.SaveStepCount != state.StepCount ||
				metadata.Agent != state.AgentType ||
				metadata.TurnID != state.TurnID ||
				metadata.Kind != string(state.Kind) ||
				len(metadata.FilesTouched) != 0 {
				continue
			}
			content, contentErr := store.ReadSessionContent(ctx, info.CheckpointID, sessionIndex)
			if contentErr != nil {
				candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d content: %w", info.CheckpointID, sessionIndex, contentErr))
				continue
			}
			if content == nil {
				candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d content: %w", info.CheckpointID, sessionIndex, cpkg.ErrCheckpointNotFound))
				continue
			}
			if bytes.Equal(content.Transcript, expectedTranscript) {
				return info.CheckpointID, true, nil
			}
		}
	}
	if len(candidateErrors) > 0 {
		return id.EmptyCheckpointID, false, errors.Join(candidateErrors...)
	}
	return id.EmptyCheckpointID, false, nil
}

type interruptedCondensationRecovery struct {
	result *CondenseResult
	err    error
	done   bool
}

func recoverInterruptedCondensation(
	ctx, logCtx context.Context,
	enabled bool,
	store cpkg.PersistentStore,
	state *SessionState,
	transcript redact.RedactedBytes,
	assets []cpkg.TranscriptAsset,
	sessionData *ExtractedSessionData,
	transcriptSizeBaseline int64,
) interruptedCondensationRecovery {
	if !enabled {
		return interruptedCondensationRecovery{}
	}
	existingID, found, err := findInterruptedCondensation(ctx, store, state, transcript, assets)
	if err != nil {
		return interruptedCondensationRecovery{
			err:  fmt.Errorf("recover interrupted condensation: %w", err),
			done: true,
		}
	}
	if !found {
		return interruptedCondensationRecovery{}
	}

	state.PromptWindowResetPending = true
	logging.Info(logCtx, "recovered interrupted condensation",
		slog.String("session_id", state.SessionID),
		slog.String("checkpoint_id", existingID.String()),
	)
	return interruptedCondensationRecovery{
		result: &CondenseResult{
			CheckpointID:           existingID,
			SessionID:              state.SessionID,
			CheckpointsCount:       checkpointStepCount(state),
			FilesTouched:           sessionData.FilesTouched,
			Prompts:                sessionData.Prompts,
			TotalTranscriptLines:   sessionData.FullTranscriptLines,
			TranscriptSizeBaseline: transcriptSizeBaseline,
		},
		done: true,
	}
}

// by the outer save. The gate fixes both: nested calls in the same
// goroutine reuse the outer's state pointer (no second load, no second
// save), and only the outermost release drops the flock.
//
// Growth: the map accumulates one entry per session ID touched by this
// process and is never trimmed. Fine today because hook invocations are
// short-lived subprocesses; a future long-running daemon (status watcher,
// MCP server) would need a TTL or eviction pass.
var sessionMutationGate sync.Map // map[string]*sessionGate

type sessionGate struct {
	mu          sync.Mutex
	owner       int64 // goroutine ID of the current holder, 0 when unlocked
	depth       int
	flockRel    func()
	activeState *SessionState // shared state pointer for nested mutations
}

// goroutineID extracts the runtime goroutine ID from the stack header. Used
// only as a reentrancy key for the session mutation gate — never as a
// security boundary or for application logic. Returns -1 if the stack
// header doesn't parse: real goroutine IDs are positive, and gate.owner is
// initialised to 0, so a -1 sentinel can't falsely match the freshly-
// constructed gate (or a freshly-released one).
func goroutineID() int64 {
	var buf [64]byte
	n := runtime.Stack(buf[:], false)
	const prefix = "goroutine "
	s := string(buf[:n])
	if !strings.HasPrefix(s, prefix) {
		return -1
	}
	s = s[len(prefix):]
	end := strings.IndexByte(s, ' ')
	if end < 0 {
		return -1
	}
	id, err := strconv.ParseInt(s[:end], 10, 64)
	if err != nil {
		return -1
	}
	return id
}

// MutateSessionState is the safe load → mutate → save helper. It takes an
// OS-level advisory lock against .git/entire-session-locks/<id>.lock for the
// duration of the read+write so concurrent processes cannot lose each
// other's updates. fn receives the freshly-loaded state and mutates it in
// place; returning ErrMutationSkip skips the save. Reentrant within the same
// goroutine: nested calls share the outer's state pointer and skip the
// inner load/save, so all mutations are flushed by the outermost call.
//
// fn may hold the lock for slow operations — PostCommit's callback, for
// example, runs CondenseSession (shadow-branch tree builds, transcript
// compaction) inside the gate. That's deliberate: PostToolUse must not slip
// in mid-condense and revert CheckpointTranscriptStart or files_touched.
// A concurrent PostToolUse on the same session waits for the commit to
// finish.
//
// Returns ErrStateNotFound if the state file doesn't exist (event arrived
// before InitializeSession). Errors from fn or from load/save propagate.
//
// All session-state mutations funnel through this helper so the hot-path
// PostToolUse hook cannot revert fields written by lifecycle handlers
// (TurnEnd, PostCommit, ModelUpdate) that ran between our load and our save.
func MutateSessionState(ctx context.Context, sessionID string, fn func(*SessionState) error) error {
	if sessionID == "" {
		return ErrStateNotFound
	}
	gate, isOuter, release, err := acquireSessionGate(ctx, sessionID)
	if err != nil {
		return err
	}
	defer release()

	if !isOuter {
		// Nested call: reuse the outer's state pointer. The outer save will
		// flush our mutations; we don't load or save here.
		if gate.activeState == nil {
			return ErrStateNotFound
		}
		if err := fn(gate.activeState); err != nil && !errors.Is(err, ErrMutationSkip) {
			return err
		}
		return nil
	}

	state, err := LoadSessionState(ctx, sessionID)
	if err != nil {
		return fmt.Errorf("load session state: %w", err)
	}
	if state == nil {
		return ErrStateNotFound
	}
	gate.activeState = state
	defer func() { gate.activeState = nil }()

	if err := fn(state); err != nil {
		if errors.Is(err, ErrMutationSkip) {
			return nil
		}
		return err
	}
	if err := SaveSessionState(ctx, state); err != nil {
		return fmt.Errorf("save session state: %w", err)
	}
	return nil
}

// acquireSessionGate takes the per-process gate (in-memory) and, on the
// outermost call, the cross-process flock. Returns isOuter=true on the
// outermost call so MutateSessionState knows whether to load/save.
func acquireSessionGate(ctx context.Context, sessionID string) (gate *sessionGate, isOuter bool, release func(), err error) {
	val, _ := sessionMutationGate.LoadOrStore(sessionID, &sessionGate{})
	gate, ok := val.(*sessionGate)
	if !ok {
		return nil, false, nil, fmt.Errorf("session gate type assertion failed for %s", sessionID)
	}

	gid := goroutineID()
	gate.mu.Lock()
	if gate.owner == gid {
		gate.depth++
		gate.mu.Unlock()
		return gate, false, func() {
			gate.mu.Lock()
			gate.depth--
			gate.mu.Unlock()
		}, nil
	}
	gate.mu.Unlock()

	lockPath, err := stateLockPath(ctx, sessionID)
	if err != nil {
		return nil, false, nil, fmt.Errorf("resolve state lock path: %w", err)
	}
	// Bound the acquisition when the caller opted in (TurnStart), so a
	// best-effort mutation can't stall behind a long-running lock holder. The
	// deadline is shared across the whole path, so several mutations don't sum
	// their waits. Only the acquire is bounded — the mutation runs under the
	// original ctx.
	var flockRel func()
	if deadline, ok := sessionLockDeadlineFromContext(ctx); ok {
		acqCtx, cancel := context.WithDeadline(ctx, deadline)
		flockRel, err = flock.AcquireContext(acqCtx, lockPath)
		cancel()
	} else {
		flockRel, err = flock.Acquire(lockPath)
	}
	if err != nil {
		return nil, false, nil, fmt.Errorf("acquire state lock: %w", err)
	}

	gate.mu.Lock()
	gate.owner = gid
	gate.depth = 1
	gate.flockRel = flockRel
	gate.mu.Unlock()

	return gate, true, func() {

