package checkpoint

import (
	"context"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// fanoutStore serves all reads from the primary and fans writes out to the
// primary plus zero or more mirror backends. The primary is the source of
// truth: a write fails only if the primary write fails. Mirror writes are
// best-effort — a mirror failure is logged and swallowed so it can never break
// a checkpoint operation. Mirrors are therefore write-only and may legitimately
// lag the primary (they never receive ref-level mutations such as cleanup
// deletes or pre-push OPF re-redaction); they must not be promoted to a read or
// sync source without separate reconciliation.
type fanoutStore struct {
	primary PersistentStore
	mirrors []Writer
}

// newFanoutStore wraps a primary with mirror write fan-out. With no mirrors it
// returns the primary unchanged, so the common (no-mirror) path keeps the
// concrete store and all of its optional capabilities. When wrapping is needed,
// it preserves the optional AuthorReader capability iff the primary has it.
func newFanoutStore(primary PersistentStore, mirrors []Writer) PersistentStore {
	if len(mirrors) == 0 {
		return primary
	}
	base := &fanoutStore{primary: primary, mirrors: mirrors}
	if author, ok := primary.(AuthorReader); ok {
		return &fanoutStoreWithAuthor{fanoutStore: base, author: author}
	}
	return base
}

// The read methods are pure delegation to the primary; nolint:wrapcheck because
// re-wrapping the primary's errors here would add noise without context (same
// convention as the contract re-exports in aliases.go).

func (s *fanoutStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	return s.primary.Read(ctx, checkpointID) //nolint:wrapcheck // pure delegation to primary
}

func (s *fanoutStore) List(ctx context.Context) ([]CheckpointInfo, error) {
	return s.primary.List(ctx) //nolint:wrapcheck // pure delegation to primary
}

func (s *fanoutStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
	return s.primary.ReadSessionContent(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
}

func (s *fanoutStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error) {
	return s.primary.ReadSessionMetadata(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
}

func (s *fanoutStore) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
	return s.primary.ReadSessionPrompts(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
}

func (s *fanoutStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error) {
	return s.primary.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
}

// Write applies to the primary first; only on primary success does it fan out to
// each mirror best-effort. A mirror error is logged and dropped.
func (s *fanoutStore) Write(ctx context.Context, req WriteRequest) error {
	if err := s.primary.Write(ctx, req); err != nil {
		return err //nolint:wrapcheck // primary error is the operation's error, surfaced verbatim
	}
	for i, mirror := range s.mirrors {
		if err := mirror.Write(ctx, req); err != nil {
			logging.Warn(ctx, "checkpoint mirror write failed; primary write succeeded",
				"mirror_index", i, "error", err.Error())
		}
	}
	return nil
}

// fanoutStoreWithAuthor adds the optional AuthorReader capability when the
// wrapped primary supports it, so callers that type-assert the store to
// AuthorReader (e.g. explain's author fallback) keep working through the wrapper.
type fanoutStoreWithAuthor struct {
	*fanoutStore

	author AuthorReader
}

func (s *fanoutStoreWithAuthor) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
	return s.author.GetCheckpointAuthor(ctx, checkpointID) //nolint:wrapcheck // pure delegation to primary
}

var (
	_ PersistentStore = (*fanoutStore)(nil)
	_ PersistentStore = (*fanoutStoreWithAuthor)(nil)
	_ AuthorReader    = (*fanoutStoreWithAuthor)(nil)
)

package strategy

import (
	"context"
	"fmt"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/go-git/go-git/v6"
)

// ManualCommitStrategy implements the manual-commit strategy for session management.
// It stores checkpoints on shadow branches and condenses session logs to a
// permanent sessions branch when the user commits.
type ManualCommitStrategy struct {
	// stateStore manages session state files in .git/entire-sessions/
	stateStore *session.StateStore
	// stateStoreOnce ensures thread-safe lazy initialization
	stateStoreOnce sync.Once
	// stateStoreErr captures any error during initialization
	stateStoreErr error

	// blobFetcher, when set, is passed to the checkpoint store to enable
	// on-demand blob fetching after treeless fetches. Set via SetBlobFetcher.
	blobFetcher checkpoint.BlobFetchFunc
}

// getStateStore returns the session state store, initializing it lazily if needed.
// Thread-safe via sync.Once.
func (s *ManualCommitStrategy) getStateStore(_ context.Context) (*session.StateStore, error) {
	s.stateStoreOnce.Do(func() {
		store, err := session.NewStateStore(context.Background()) //nolint:contextcheck // sync.Once must use background context to avoid caching errors from a cancelled caller context
		if err != nil {
			s.stateStoreErr = fmt.Errorf("failed to create state store: %w", err)
			return
		}
		s.stateStore = store
	})
	return s.stateStore, s.stateStoreErr
}

func (s *ManualCommitStrategy) getCheckpointStores(ctx context.Context, repo *git.Repository) (*checkpoint.Stores, error) {
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: s.blobFetcher, ReadRemotes: CheckpointReadRemotes(ctx)})
	if err != nil {
		return nil, fmt.Errorf("open checkpoint store: %w", err)
	}
	return stores, nil
}

// getPersistentStore returns a store bound to the resolved committed-metadata
// topology. Writes target refs.Primary; reads target refs.Read. The strategy's
// blob fetcher is wired in so reads can fetch blobs on demand after a treeless
// fetch.
func (s *ManualCommitStrategy) getPersistentStore(ctx context.Context, repo *git.Repository) (checkpoint.PersistentStore, error) {
	stores, err := s.getCheckpointStores(ctx, repo)
	if err != nil {
		return nil, err
	}
	return stores.Persistent, nil
}

// getEphemeralStore returns the git-backed shadow-branch store with the
// strategy's blob fetcher wired in.
func (s *ManualCommitStrategy) getEphemeralStore(ctx context.Context, repo *git.Repository) (checkpoint.EphemeralStore, error) {
	stores, err := s.getCheckpointStores(ctx, repo)
	if err != nil {
		return nil, err
	}
	return stores.Ephemeral(), nil
}

// NewManualCommitStrategy creates a new manual-commit strategy instance.
func NewManualCommitStrategy() *ManualCommitStrategy {
	return &ManualCommitStrategy{}
}

// SetBlobFetcher configures on-demand blob fetching for the checkpoint store.
// Must be called before the first checkpoint store access (e.g., before RestoreLogsOnly).
func (s *ManualCommitStrategy) SetBlobFetcher(f checkpoint.BlobFetchFunc) {

	"add dark mode support",
	"migrate to the new API version",
	"fix the memory leak in the worker pool",
	"add retry logic for failed API calls",
	"implement webhook support",
	"clean up unused imports and dead code",
}

type hookPerfFixture struct {
	endedWithShadow []hookPerfEndedSession
}

type hookPerfEndedSession struct {
	sessionID  string
	baseCommit string
	shadowRef  plumbing.ReferenceName
}

// seedHookPerfSessions creates realistic session states and shadow checkpoints.
// Every uncondensed ENDED session gets a unique base, transcript, tree, and ref.
//
// Phase distribution matches real-world observations from .git/entire-sessions/:
//
//	ENDED sessions (75%): shadow branch ref + data, NO LastCheckpointID.
//	    These exercise the expensive hot path: ref lookup → commit → tree →
//	    transcript/overlap check → condensation during PostCommit.
//	ENDED sessions (25%): state file with LastCheckpointID (already committed, cheap).
//	IDLE sessions:  state file + shadow branch checkpoint via SaveStep.
//	ACTIVE sessions: state file + shadow branch + live transcript file.
func seedHookPerfSessions(t *testing.T, dir string, baseCommits []string, ended, idle, active int) hookPerfFixture {
	t.Helper()

	ctx := context.Background()

	worktreeID, err := paths.GetWorktreeID(dir)
	if err != nil {
		t.Fatalf("worktree ID: %v", err)
	}

	stateDir := filepath.Join(dir, ".git", session.SessionStateDirName)
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		t.Fatalf("mkdir state dir: %v", err)
	}
	store := session.NewStateStoreWithDir(stateDir)

	agentTypes := []types.AgentType{
		agent.AgentTypeClaudeCode,
		agent.AgentTypeClaudeCode,
		agent.AgentTypeClaudeCode,
		agent.AgentTypeGemini,
		agent.AgentTypeOpenCode,
	}

	s := &ManualCommitStrategy{}
	fixture := hookPerfFixture{}

	// --- Seed ENDED sessions ---
	// Real-world distribution (from .git/entire-sessions/ analysis):
	//   ~75% have shadow branches with data but no LastCheckpointID (not yet committed)
	//   ~25% have LastCheckpointID set and no shadow branch (already committed)
	//
	// The 75% exercise the expensive hot path per session:
	//   listAllSessionStates: packed-refs linear scan to resolve shadow branch ref
	//   sessionHasNewContent: ref → commit → tree → transcript/overlap check
	//   PostCommit condensation: write metadata to entire/checkpoints/v1 branch
	endedWithShadow := ended * 3 / 4
	endedWithoutShadow := ended - endedWithShadow

	if endedWithShadow > 0 {
		repo, openErr := gitrepo.OpenPath(dir)
		if openErr != nil {
			t.Fatalf("open repo for shadow checkpoints: %v", openErr)
		}
		ephemeral, storeErr := s.getEphemeralStore(ctx, repo)
		if storeErr != nil {
			repo.Close()
			t.Fatalf("open ephemeral store: %v", storeErr)
		}

		for i := range endedWithShadow {
			sessionID := fmt.Sprintf("perf-ended-%d", i)
			base := baseCommits[i]
			metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
			metadataDirAbs := filepath.Join(dir, metadataDir)
			if mkdirErr := os.MkdirAll(metadataDirAbs, 0o755); mkdirErr != nil {
				repo.Close()
				t.Fatalf("mkdir ended metadata %d: %v", i, mkdirErr)
			}
			transcript := fmt.Sprintf("{\"type\":\"human\",\"message\":{\"content\":%q}}\n{\"type\":\"assistant\",\"message\":{\"content\":%q}}\n",
				perfPrompts[i%len(perfPrompts)], fmt.Sprintf("completed work for %s", sessionID))
			if writeErr := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); writeErr != nil {
				repo.Close()
				t.Fatalf("write ended transcript %d: %v", i, writeErr)
			}

			result, writeErr := ephemeral.Write(ctx, checkpoint.Step{
				SessionID:         sessionID,
				BaseCommit:        base,
				WorktreeID:        worktreeID,
				NewFiles:          []string{"perf_control.txt"},
				MetadataDir:       metadataDir,
				MetadataDirAbs:    metadataDirAbs,
				CommitMessage:     "Checkpoint 1",
				AuthorName:        "Perf",
				AuthorEmail:       "perf@test.com",
				IsFirstCheckpoint: true,
			})
			if writeErr != nil {
				repo.Close()
				t.Fatalf("write ended shadow checkpoint %d: %v", i, writeErr)
			}
			if result.Skipped {
				repo.Close()
				t.Fatalf("ended shadow checkpoint %d was unexpectedly skipped", i)
			}

			now := time.Now()
			endedAt := now.Add(-time.Duration((i%144)+1) * time.Hour)
			state := &session.State{
				SessionID:             sessionID,
				CLIVersion:            "dev",
				BaseCommit:            base,
				AttributionBaseCommit: base,
				WorktreePath:          dir,
				WorktreeID:            worktreeID,
				Phase:                 session.PhaseEnded,
				StartedAt:             endedAt.Add(-time.Hour),
				EndedAt:               &endedAt,
				StepCount:             (i % 5) + 1,
				FilesTouched:          perfLargeFileSets[i%len(perfLargeFileSets)],
				LastInteractionTime:   &now,
				AgentType:             agentTypes[i%len(agentTypes)],
				LastPrompt:            perfPrompts[i%len(perfPrompts)],
			}
			if saveErr := store.Save(ctx, state); saveErr != nil {
				repo.Close()
				t.Fatalf("save ended-shadow state %d: %v", i, saveErr)
			}

			shadowName := checkpoint.ShadowBranchNameForCommit(base, worktreeID)
			fixture.endedWithShadow = append(fixture.endedWithShadow, hookPerfEndedSession{
				sessionID:  sessionID,
				baseCommit: base,
				shadowRef:  plumbing.NewBranchReferenceName(shadowName),
			})
		}
		if closeErr := repo.Close(); closeErr != nil {
			t.Fatalf("close repo after shadow checkpoints: %v", closeErr)
		}
	}

	// Already-committed ENDED sessions (25%): state file only, no shadow branch.
	// These have LastCheckpointID set — cheap path during hooks.
	for i := range endedWithoutShadow {
		idx := endedWithShadow + i
		sessionID := fmt.Sprintf("perf-ended-%d", idx)
		cpID := mustGenerateCheckpointID(t)
		now := time.Now()
		baseIdx := (idx + 1) % len(baseCommits)
		base := baseCommits[baseIdx]

		state := &session.State{
			SessionID:           sessionID,
			CLIVersion:          "dev",
			BaseCommit:          base,
			WorktreePath:        dir,
			WorktreeID:          worktreeID,
			Phase:               session.PhaseEnded,
			StartedAt:           now.Add(-time.Duration((idx%144)+1) * time.Hour),
			LastCheckpointID:    cpID,
			StepCount:           (idx % 5) + 1,
			FilesTouched:        perfLargeFileSets[idx%len(perfLargeFileSets)],
			LastInteractionTime: &now,
			AgentType:           agentTypes[idx%len(agentTypes)],
			LastPrompt:          perfPrompts[idx%len(perfPrompts)],
		}
		if saveErr := store.Save(ctx, state); saveErr != nil {
			t.Fatalf("save ended-committed state %d: %v", i, saveErr)
		}
	}

	// --- Seed IDLE sessions (with shadow branches) ---
	// IDLE sessions have the current HEAD as base commit (they're recent).
	for i := range idle {
		sessionID := fmt.Sprintf("perf-idle-%d", i)
		files := perfFileSets[i%len(perfFileSets)]
		seedSessionWithShadowBranch(t, s, dir, sessionID, session.PhaseIdle, files)

